* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: radial-gradient(circle at top left, #dff7f2, transparent 34%), #f8fbff;
  color: #102033;
}

.nav {
  width: min(1120px, calc(100% - 40px));
  margin: 24px auto;
  padding: 18px 22px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid rgba(16, 32, 51, 0.08);
  border-radius: 22px;
  backdrop-filter: blur(18px);
  box-shadow: 0 20px 60px rgba(26, 72, 110, 0.08);
}

.brand {
  font-size: 1.25rem;
  font-weight: 800;
  color: #0f766e;
}

.nav-links {
  display: flex;
  gap: 22px;
}

.nav-links a {
  color: #425466;
  text-decoration: none;
  font-weight: 600;
}

.hero {
  width: min(1120px, calc(100% - 40px));
  min-height: 68vh;
  margin: 40px auto;
  display: grid;
  grid-template-columns: 1.25fr 0.75fr;
  align-items: center;
  gap: 36px;
}

.eyebrow {
  color: #0f766e;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.76rem;
  font-weight: 800;
}

h1 {
  margin: 0;
  font-size: clamp(2.7rem, 6vw, 5.6rem);
  line-height: 0.95;
  letter-spacing: -0.07em;
}

.hero-text {
  max-width: 620px;
  margin: 24px 0;
  font-size: 1.1rem;
  line-height: 1.8;
  color: #526173;
}

.hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

button {
  border: 0;
  border-radius: 999px;
  padding: 14px 22px;
  font-weight: 800;
  cursor: pointer;
}

.primary-btn {
  color: white;
  background: linear-gradient(135deg, #0f766e, #14b8a6);
  box-shadow: 0 16px 35px rgba(20, 184, 166, 0.28);
}

.secondary-btn {
  color: #0f766e;
  background: white;
  border: 1px solid rgba(15, 118, 110, 0.18);
}

.hero-card {
  padding: 34px;
  border-radius: 34px;
  background: linear-gradient(180deg, white, #eefaf8);
  border: 1px solid rgba(15, 118, 110, 0.12);
  box-shadow: 0 30px 90px rgba(16, 32, 51, 0.14);
}

.status-pill {
  display: inline-flex;
  padding: 8px 12px;
  border-radius: 999px;
  background: #dcfce7;
  color: #166534;
  font-weight: 800;
  font-size: 0.8rem;
}

.hero-card h2 {
  font-size: 2rem;
  margin-bottom: 8px;
}

.hero-card strong {
  display: block;
  font-size: 3rem;
  color: #0f766e;
  margin: 10px 0 24px;
}

.mini-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.mini-grid span,
.service-grid article {
  padding: 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.8);
  border: 1px solid rgba(16, 32, 51, 0.08);
}

.services {
  width: min(1120px, calc(100% - 40px));
  margin: 60px auto 90px;
}

.services h2 {
  max-width: 620px;
  font-size: clamp(2rem, 4vw, 3.5rem);
  letter-spacing: -0.05em;
}

.service-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.service-grid h3 {
  margin-top: 0;
}

.service-grid p {
  color: #526173;
  line-height: 1.7;
}

@media (max-width: 780px) {
  .hero,
  .service-grid {
    grid-template-columns: 1fr;
  }

  .nav {
    align-items: flex-start;
    gap: 12px;
    flex-direction: column;
  }
}
